func VerifyDataColumnSidecar(sidecar blocks.RODataColumn) error {
    if len(sidecar.Column) != len(sidecar.KzgCommitments) || len(sidecar.Column) != len(sidecar.KzgProofs) {
        return ErrMismatchLength
    }
    return nil
}
// SSZ UnmarshalSSZ enforces KzgProofs[ii] exactly 48 bytes via DivideInt2(len(buf),48,4096)

// Single for-range loop builds all 4 slices in parallel
for _, sidecar := range sidecars {
    for i := range sidecar.Column {
        commitments = append(commitments, kzg.Bytes48(sidecar.KzgCommitments[i]))
        indices = append(indices, sidecar.Index)
        cells = append(cells, kzg.Cell(sidecar.Column[i]))
        proofs = append(proofs, kzg.Bytes48(sidecar.KzgProofs[i]))
    }
}

// Gossip path: decodePubsubMessage -> s.cfg.p2p.Encoding().DecodeGossip(msg.Data, m)
// DecodeGossip: snappy decompression + UnmarshalSSZ
// UnmarshalSSZ enforces: KzgProofs[ii] = 48 bytes, KzgCommitments[ii] = 48 bytes, Column[ii] = 2048 bytes
// verifier.ValidFields() -> VerifyDataColumnSidecar: len(Column)==len(KzgCommitments)==len(KzgProofs)

// PeerDAS path: commitments passed as kzg.Bytes48 (raw [48]byte) to ckzg4844.VerifyCellKZGProofBatch
// C library: bytes_to_kzg_commitment -> validate_kzg_g1 -> blst_p1_uncompress + blst_p1_in_g1
// No Go-level subgroup check; delegated entirely to c-kzg-4844 library

// Theoretical impact if non-subgroup G1 points were accepted in VerifyCellKZGProofBatch:
// Small-subgroup attack via cofactor-order point P' of order r | h (cofactor h=76329603384216526031706109802092473003)
// Randomized linear combination r_powers derived from H(commitment_bytes || ...) does not prevent manipulation
// when adversary controls input bytes

// Non-subgroup commitment bytes traverse the full pre-KZG pipeline before rejection:
// SSZ decode (48-byte enforcement) -> ValidFields (count check) -> InclusionProven (Merkle proof)
// -> validateWithKzgBatchVerifier -> VerifyDataColumnsSidecarKZGProofs -> c-kzg-4844
// Subgroup check occurs at C library boundary only (late rejection)

// kzg.VerifyCellKZGProofBatch wrapper: no pre-validation, delegates entirely to c-kzg-4844
// C library deduplicates commitments, then calls validate_kzg_g1 for each UNIQUE commitment
// Deduplication does NOT skip validation: each unique commitment is independently validated

// Two KZG libraries:
// 1. c-kzg-4844 v2.1.1 (CGo/blst): VerifyCellKZGProofBatch - PeerDAS path
// 2. go-kzg-4844 v1.1.0 (gnark-crypto): kzgContext.VerifyBlobKZGProof - blob path
// Both implement BLS12-381 G1 subgroup checks via different underlying implementations

// c-kzg-4844 deduplicate_commitments: find-or-insert algorithm
// commitment_indices[k] = j iff unique_commitments[j] == commitments_bytes[k]
// Uses byte equality (memcmp 48 bytes) = semantic equality for valid BLS12-381 compressed points
// (canonical encoding uniqueness: each G1 point has exactly one valid compressed form)

// commitment_indices mapping is surjective (many-to-one for duplicates) and bijective on equivalence classes
// Forward: k -> j where unique_commitments[j] == commitments_bytes[k]
// Equivalence class {k: commitments_bytes[k] == C} maps to exactly one j in unique_commitments

// verifyKzgBatch (batch_verifier.go) aggregates data columns from multiple concurrent P2P peers
// into a single VerifyDataColumnsSidecarKZGProofs call.
// If ANY column fails, ALL batch participants receive the error and fall back to individual verification.
// Attacker can time invalid sidecar to coincide with honest sidecars in the batch.

// Impact if commitment_indices had off-by-one:
// Pairing check fails (false negative - valid data rejected) NOT passes (false positive - invalid data accepted)
// Worst case: DoS for validator missing DA check for affected slot/column

func MinimumColumnCountToReconstruct() uint64 {
    return (params.BeaconConfig().NumberOfColumns + 1) / 2  // = (128+1)/2 = 64
}

// Check occurs BEFORE C library call:
if uint64(sidecarCount) < MinimumColumnCountToReconstruct() {
    return nil, ErrNotEnoughDataColumnSidecars
}
// C library also checks: if (num_cells < CELLS_PER_BLOB) -> C_KZG_BADARGS
// CELLS_PER_BLOB = 64 = CELLS_PER_EXT_BLOB/2 = 128/2

// Constants (both mainnet and minimal):
// fieldparams.NumberOfColumns = 128 (compile-time)
// fieldparams.CellsPerBlob = 64 (compile-time)
// params.BeaconConfig().NumberOfColumns = 128 (runtime)
// MinimumColumnCountToReconstruct() = (128+1)/2 = 64 (ceiling division)
// CELLS_PER_BLOB (c-kzg) = FIELD_ELEMENTS_PER_BLOB/FIELD_ELEMENTS_PER_CELL = 4096/64 = 64
// All independent representations agree: minimum = 64 = 50% of 128
